#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\GLOOWS365E-MONOREPO\node_modules\.pnpm\expo@54.0.35_@babel+core@7._c9fab2e76ad171119476834cf0ac5023\node_modules\expo\node_modules;C:\GLOOWS365E-MONOREPO\node_modules\.pnpm\expo@54.0.35_@babel+core@7._c9fab2e76ad171119476834cf0ac5023\node_modules;C:\GLOOWS365E-MONOREPO\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/GLOOWS365E-MONOREPO/node_modules/.pnpm/expo@54.0.35_@babel+core@7._c9fab2e76ad171119476834cf0ac5023/node_modules/expo/node_modules:/mnt/c/GLOOWS365E-MONOREPO/node_modules/.pnpm/expo@54.0.35_@babel+core@7._c9fab2e76ad171119476834cf0ac5023/node_modules:/mnt/c/GLOOWS365E-MONOREPO/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../expo/bin/autolinking" $args
